import { useState, KeyboardEvent } from 'react';
import { JxInput, JxTag, JxStack } from '@jinx-ui/react';

interface TagInputProps {
  onChange?: (tags: string[]) => void;
}

export default function TagInput({ onChange }: TagInputProps) {
  const [tags, setTags] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState('');

  const addTag = (rawValue: string) => {
    const value = rawValue.trim();
    if (!value || tags.includes(value)) return;

    const nextTags = [...tags, value];
    setTags(nextTags);
    onChange?.(nextTags);
  };

  const removeTag = (tagToRemove: string) => {
    const nextTags = tags.filter((tag) => tag !== tagToRemove);
    setTags(nextTags);
    onChange?.(nextTags);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(inputValue);
      setInputValue('');
    } else if (event.key === 'Backspace' && inputValue === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const handleBlur = () => {
    if (inputValue.trim()) {
      addTag(inputValue);
      setInputValue('');
    }
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-2)" className="jx-tag-input">
      <JxInput
        value={inputValue}
        onChange={(event) => setInputValue(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={handleBlur}
        placeholder="Добавьте тег и нажмите Enter"
        aria-label="Ввод тегов статьи"
      />
      {tags.length > 0 && (
        <JxStack direction="row" gap="var(--jx-space-1)" wrap className="jx-tag-input__list">
          {tags.map((tag) => (
            <JxTag
              key={tag}
              variant="removable"
              onRemove={() => removeTag(tag)}
              aria-label={`Удалить тег ${tag}`}
            >
              {tag}
            </JxTag>
          ))}
        </JxStack>
      )}
    </JxStack>
  );
}

